export const DICTIONARIES: Record<Lang, Record<MsgKey, string>> = { en, uk }

/** The browser's language as one of ours: Ukrainian locales get uk, the rest en. */
export function detectLanguage(nav: string | undefined = typeof navigator === 'undefined' ? undefined : navigator.language): Lang {
  return (nav ?? '').toLowerCase().startsWith('uk') ? 'uk' : 'en'
}

/** The effective language for a stored setting value. Settings from before 4.20 hold a
 *  language name ("English", the old seed default): read it, do not fall back to the browser. */
export function resolveLanguage(setting: unknown): Lang {
  if (setting === 'uk' || setting === 'en') return setting
  const name = typeof setting === 'string' ? setting.trim().toLowerCase() : ''
  if (name.startsWith('english')) return 'en'
  if (name.startsWith('ukrain') || name.startsWith('україн')) return 'uk'
  return detectLanguage()
}

let current: Lang = detectLanguage()

/** Called by useT whenever the setting changes. */
export function setLanguage(setting: unknown): Lang {
  current = resolveLanguage(setting)
  return current
}

export type Vars = Record<string, string | number>

/** The plural category order a `{n|…}` form list follows (Intl's own names, the forms a language has). */
const PLURAL_ORDER = ['zero', 'one', 'two', 'few', 'many', 'other']
const pluralRules = new Map<Lang, Intl.PluralRules>()
/** The word form for a count: `{n|entry|entries}` (en: one, other), `{n|запис|записи|записів}`
 *  (uk: one, few, many); a missing form falls back to the last one. */
function pluralForm(lang: Lang, count: number, forms: string[]): string {
  let rules = pluralRules.get(lang)
  if (!rules) pluralRules.set(lang, (rules = new Intl.PluralRules(lang)))
  const cats = PLURAL_ORDER.filter((c) => rules.resolvedOptions().pluralCategories.includes(c as Intl.LDMLPluralRule))
  const i = cats.indexOf(rules.select(count))
  return forms[Math.min(i < 0 ? forms.length - 1 : i, forms.length - 1)] ?? ''
}

/** Translate a key into the current language (or an explicit one); `{name}`
 *  placeholders are filled from vars, `{name|form|form…}` picks the plural form for that count. */
export function t(key: MsgKey, lang: Lang = current, vars?: Vars): string {
  const s = DICTIONARIES[lang][key] ?? en[key]
  if (!vars) return s
  return s
    .replace(/\{(\w+)\|([^{}]*)\}/g, (m, k: string, forms: string) => (k in vars ? pluralForm(lang, Number(vars[k]), forms.split('|')) : m))
    .replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m))
}

/** "just now", "5m ago", "2h ago", … in the given language. */
export function relativeTime(ts: number, lang: Lang = current, now = Date.now()): string {
  const m = Math.floor((now - ts) / 60000)
  if (m < 1) return t('time.now', lang)
  if (m < 60) return t('time.m', lang, { n: m })
  const h = Math.floor(m / 60)
  if (h < 24) return t('time.h', lang, { n: h })
  const d = Math.floor(h / 24)
  if (d < 30) return t('time.d', lang, { n: d })
  return t('time.mo', lang, { n: Math.floor(d / 30) })
}
